D.QuestTemplates[41193]={Objectives={source={{4,"7c96cb66bdd9a379:4"},1,{101,"e02ad919cc2f16e4:101"}},values={1},text="找到~1~塊艾切羅的骸骨碎片，交給高嶺的蕾莎。然後觀察蕾莎所做的葬禮。"}}
