D.QuestTemplates[48067]={Objectives={source={{4,"7c9df77e1c1f6891:4"},1,{15,"44090dbf91ecbfbc:15"},2,{27,"bf70067793658300:27"}},values={1,2},text="在雷霆崖消灭~1~条黑暗触须和~2~个乌尔之影。"}}
D.QuestTemplates[49782]={Description={source={{46,"d35b85eef4166db5:46"},1,{122,"e1de850763fe8e38:122"}},values={-1},text="你对联盟的帮助令人印象深刻，~1~。换了我也不可能做得更好。呃，或许可以……但也好不了太多。\n\n来吧，到维迪卡尔来见我。我们该嘉奖你的勤勉了。"}}
D.QuestTemplates[49783]={Description={source={{37,"4e5626b4343785df:37"},1,{124,"a292ae0dcf6e2c78:124"}},values={-1},text="你在艾泽拉斯旅行了很久，~1~。在这段时间里，你为至高岭带来了荣耀。\n\n现在，至高岭正在召唤你回家。我们觉得是时候了，应该感谢你为我们所做的一切。"}}
D.QuestTemplates[49788]={Description={source={{388,"4fb2968f2dc95e0c:388"},1,{1,"0002b5d30000002e:1"}},values={-1},text="要掌控虚空低语，需要无时无刻的专注和自律。你的奉献鼓舞了所有朗多雷——因为我们已是虚空之子。\n\n你在我这里学了很多，是时候去泰洛古斯裂隙之外冒险了。\n\n去联盟的心脏暴风城。国王的使者会在那里迎接你，并指引你的旅程。\n\n我们必须守护艾泽拉斯。你是我能想到回应这一号召的最佳人选，~1~。"}}
D.QuestTemplates[49928]={Description={source={{146,"35239dbc470eae99:146"},1,{55,"0f27f78ec26a1453:55"}},values={-1},text="经过在艾泽拉斯的冒险之旅， 这股力量虽然总想控制你，但终于为你所用。\n\n你已经成为了联盟的强大武器，~1~。回到虚空裂隙，让我们来嘉奖你的成就吧。"}}
